sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.currentDate = new Date();
    c.calendarDays = [];
    c.monthLabel = "";

    c.buildCalendar = function() {

        c.calendarDays = [];

        var year = c.currentDate.getFullYear();
        var month = c.currentDate.getMonth();

        var firstDay =
            new Date(year, month, 1);

        var lastDay =
            new Date(year, month + 1, 0);

        var startOffset =
            firstDay.getDay();

        var calendarStart =
            new Date(year, month, 1 - startOffset);

        var monthNames = [
            "January", "February", "March",
            "April", "May", "June",
            "July", "August", "September",
            "October", "November", "December"
        ];

        c.monthLabel =
            monthNames[month] + " " + year;


        for (var i = 0; i < 42; i++) {

            var dayDate =
                new Date(calendarStart);

            dayDate.setDate(
                calendarStart.getDate() + i
            );

            var dayObj = {

                date:
                    dayDate,

                dayNumber:
                    dayDate.getDate(),

                currentMonth:
                    dayDate.getMonth() == month,

                leaves: []

            };


            angular.forEach(
                c.data.leaves,
                function(leave) {

                    if (!leave.start_date ||
                        !leave.end_date) {
                        return;
                    }

                    var start =
                        new Date(leave.start_date);

                    var end =
                        new Date(leave.end_date);

                    var check =
                        new Date(
                            dayDate.getFullYear(),
                            dayDate.getMonth(),
                            dayDate.getDate()
                        );

                    start =
                        new Date(
                            start.getFullYear(),
                            start.getMonth(),
                            start.getDate()
                        );

                    end =
                        new Date(
                            end.getFullYear(),
                            end.getMonth(),
                            end.getDate()
                        );

                    if (check >= start &&
                        check <= end) {

                        dayObj.leaves.push(
                            leave
                        );

                    }

                }
            );

            c.calendarDays.push(dayObj);

        }

    };


    c.previousMonth = function() {

        c.currentDate.setMonth(
            c.currentDate.getMonth() - 1
        );

        c.currentDate =
            new Date(c.currentDate);

        c.buildCalendar();

    };


    c.nextMonth = function() {

        c.currentDate.setMonth(
            c.currentDate.getMonth() + 1
        );

        c.currentDate =
            new Date(c.currentDate);

        c.buildCalendar();

    };


    c.buildCalendar();

};

sp_widget.css:
.leave-calendar-page {
  max-width: 1280px;
  margin: 0 auto;
  padding: 34px 30px 60px;
  min-height: 100vh;
  background: #f7f9fc;
  color: #0f1b45;
  font-family: Arial, sans-serif;
}

.calendar-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.calendar-header h2 {
  margin: 0 0 6px;
  font-size: 28px;
  font-weight: 700;
  color: #0f1b45;
}

.calendar-header p {
  margin: 0;
  color: #7d879c;
  font-size: 13px;
}

.month-controls {
  display: flex;
  align-items: center;
  gap: 14px;
}

.month-controls button {
  width: 36px;
  height: 36px;
  border: 1px solid #dfe5ed;
  background: #ffffff;
  border-radius: 8px;
  color: #0b8793;
  font-size: 22px;
  line-height: 1;
}

.month-controls strong {
  min-width: 130px;
  text-align: center;
  font-size: 14px;
}

.legend-card {
  display: flex;
  gap: 24px;
  background: #ffffff;
  border: 1px solid #e2e7ef;
  border-radius: 12px;
  padding: 14px 18px;
  margin-bottom: 18px;
  box-shadow: 0 3px 12px rgba(15,27,69,.04);
}

.legend-card span {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 11px;
  color: #4b5871;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

.dot.approved {
  background: #22c55e;
}

.dot.pending {
  background: #f59e0b;
}

.dot.rejected {
  background: #ef4444;
}

.calendar-card {
  background: #ffffff;
  border: 1px solid #e2e7ef;
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 4px 14px rgba(15,27,69,.05);
}

.week-row {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  background: #f5f7fb;
  border-bottom: 1px solid #e2e7ef;
}

.week-row div {
  padding: 13px;
  text-align: center;
  font-size: 11px;
  font-weight: 700;
  color: #475569;
}

.calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
}

.calendar-day {
  min-height: 125px;
  padding: 9px;
  border-right: 1px solid #edf1f5;
  border-bottom: 1px solid #edf1f5;
  background: #ffffff;
}

.calendar-day:nth-child(7n) {
  border-right: none;
}

.other-month {
  background: #fafbfc;
  color: #b0b7c3;
}

.date-number {
  font-size: 11px;
  font-weight: 700;
  margin-bottom: 7px;
}

.leave-event {
  padding: 6px 7px;
  margin-bottom: 5px;
  border-radius: 7px;
  font-size: 9px;
  line-height: 1.3;
}

.leave-event strong {
  display: block;
  font-size: 9px;
}

.leave-event span {
  opacity: .85;
}

.event-approved {
  background: #dcfce7;
  color: #15803d;
}

.event-pending {
  background: #fff2d9;
  color: #c97800;
}

.event-rejected {
  background: #fee2e2;
  color: #c62828;
}

@media(max-width: 900px) {
  .calendar-card {
    overflow-x: auto;
  }

  .week-row,
  .calendar-grid {
    min-width: 850px;
  }

  .calendar-header {
    display: block;
  }

  .month-controls {
    margin-top: 14px;
  }
}

sp_widget.script:
(function() {

    data.leaves = [];

    var gr = new GlideRecord('x_snc_unified_hr_0_leave_request');

    gr.addQuery('status', 'IN', 'approved,pending_hr,rejected');
    gr.orderBy('start_date');
    gr.query();

    while (gr.next()) {

        data.leaves.push({

            sys_id:
                gr.getUniqueValue(),

            number:
                gr.getDisplayValue('number'),

            employee:
                gr.getDisplayValue('requested_by'),

            leave_type:
                gr.getDisplayValue('leave_type'),

            start_date:
                gr.getValue('start_date'),

            end_date:
                gr.getValue('end_date'),

            status:
                gr.getDisplayValue('status'),

            status_value:
                gr.getValue('status')

        });

    }

})();
